      kp=[("93% w/v: 93 g H2SO4 per 100 ml, so 930 g in 1 L = 930/98 = 9.49 mol", 1), ("Mass of 1 L solution = 1000 × 1.84 = 1840 g; mass of water = 1840 − 930 = 910 g = 0.910 kg", 1),
          ("Molality = 9.49 / 0.910 ≈ 10.4 mol/kg", 1)],
